"""Tropical census laboratory: fingerprints, corners, and collisions.

A focused companion to the main verification suite.  For each semiprime it

  * computes the 2-Sylow torsion census T(k) by direct enumeration of the units,
  * checks it against the closed form 2^(min(k,a)+min(k,b)), a = v2(p-1), b = v2(q-1),
  * extracts the tropical corner locus (the roots a, b) from finite differences alone,
  * hunts for collisions: distinct semiprimes whose census -- or whose entire torsion
    profile over all exponents -- coincides.

The output is a table of what the census knows (an unordered pair of 2-adic levels)
and what it cannot know (which factor carries which level).
"""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Sequence, Tuple


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def v2(m: int) -> int:
    k = 0
    while m % 2 == 0:
        m //= 2
        k += 1
    return k


def census_bruteforce(n: int, k_max: int) -> List[int]:
    """T(k) by enumerating the units of Z/nZ."""
    units = [x for x in range(1, n) if gcd(x, n) == 1]
    return [sum(1 for x in units if pow(x, 2 ** k, n) == 1) for k in range(k_max + 1)]


def census_formula(p: int, q: int, k_max: int) -> List[int]:
    a, b = v2(p - 1), v2(q - 1)
    return [2 ** (min(k, a) + min(k, b)) for k in range(k_max + 1)]


def corner_locus_from_census(census: Sequence[int]) -> Tuple[int, int]:
    """Recover the tropical roots from the census alone, by differencing."""
    exps = [t.bit_length() - 1 for t in census]
    slopes = [exps[k + 1] - exps[k] for k in range(len(exps) - 1)]
    lo = next(k for k in range(len(slopes)) if slopes[k] < 2)
    hi = next(k for k in range(len(slopes)) if slopes[k] == 0)
    return lo, hi


def profile(p: int, q: int, d: int) -> int:
    return gcd(p - 1, d) * gcd(q - 1, d)


def local_key(p: int, q: int) -> Tuple[Tuple[int, Tuple[int, int]], ...]:
    """Local valuation multisets of (p-1, q-1) at every relevant prime."""
    def support(m: int) -> List[int]:
        out, n = [], m
        d = 2
        while d * d <= n:
            if n % d == 0:
                out.append(d)
                while n % d == 0:
                    n //= d
            d += 1
        if n > 1:
            out.append(n)
        return out

    def val(m: int, l: int) -> int:
        k = 0
        while m % l == 0:
            m //= l
            k += 1
        return k

    primes = sorted(set(support(p - 1)) | set(support(q - 1)))
    return tuple((l, tuple(sorted((val(p - 1, l), val(q - 1, l))))) for l in primes)


def main() -> None:
    print("A. Census, closed form, and recovered corner locus")
    print("-" * 68)
    for p, q in ((3, 7), (5, 13), (7, 11), (17, 41), (13, 29)):
        n = p * q
        bf = census_bruteforce(n, 6)
        fm = census_formula(p, q, 6)
        assert bf == fm, (bf, fm)
        roots = corner_locus_from_census(fm)
        print(f"N = {n:5d} = {p:3d}*{q:3d}  T(k) = {fm}")
        print(f"            true fingerprint {{{v2(p-1)}, {v2(q-1)}}}   "
              f"recovered from differences {set(roots)}")

    print("\nB. Census collisions: same tropical roots, different factors")
    print("-" * 68)
    primes = [x for x in range(3, 120) if is_prime(x)]
    buckets: Dict[Tuple[int, int], List[Tuple[int, int]]] = {}
    for i, p in enumerate(primes):
        for q in primes[i + 1:]:
            if p * q > 2000:
                break
            key = tuple(sorted((v2(p - 1), v2(q - 1))))
            buckets.setdefault(key, []).append((p, q))  # type: ignore[arg-type]
    for key, group in sorted(buckets.items())[:4]:
        shown = ", ".join(f"{p*q} = {p}*{q}" for p, q in group[:6])
        print(f"fingerprint {set(key)}: {shown} ...  ({len(group)} semiprimes share this census)")

    print("\nC. Full-profile collisions: root shuffling between the two factors")
    print("-" * 68)
    pbuckets: Dict[object, List[Tuple[int, int]]] = {}
    for i, p in enumerate(primes):
        for q in primes[i + 1:]:
            if p * q > 2000:
                break
            pbuckets.setdefault(local_key(p, q), []).append((p, q))
    found = 0
    for group in pbuckets.values():
        if len(group) < 2:
            continue
        (p1, q1), (p2, q2) = group[0], group[1]
        vals1 = [profile(p1, q1, d) for d in range(1, 25)]
        vals2 = [profile(p2, q2, d) for d in range(1, 25)]
        assert vals1 == vals2
        print(f"{p1*q1:5d} = {p1}*{q1}  and  {p2*q2:5d} = {p2}*{q2}: "
              f"identical profile {vals1[:8]} ...")
        found += 1
        if found == 8:
            break
    print("\nEvery collision is a proof that the statistic cannot locate a factor.")


if __name__ == "__main__":
    main()

