"""Exact evaluation of the 2-Sylow torsion census of a squarefree modulus.

T_N(k) = #{x mod N : x^(2^k) = 1} = 2^(sum_{p | N} min(k, v2(p-1))).
"""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Sequence


def v2(m: int) -> int:
    """2-adic valuation of m >= 1 (count of trailing zero bits)."""
    if m <= 0:
        raise ValueError("v2 requires a positive integer")
    k = 0
    while m % 2 == 0:
        m //= 2
        k += 1
    return k


def census_levels(primes: Sequence[int]) -> List[int]:
    """The multiset of tropical roots {v2(p-1)} of the census polynomial."""
    return [v2(p - 1) for p in primes]


def census_exponent(levels: Sequence[int], k: int) -> int:
    """Value at X = k of the tropical polynomial (*)_i (X (+) level_i)."""
    return sum(min(k, a) for a in levels)


def torsion_census(primes: Sequence[int], k_max: int) -> List[int]:
    """T_N(k) for k = 0..k_max, where N is the product of the given primes."""
    levels = census_levels(primes)
    return [2 ** census_exponent(levels, k) for k in range(k_max + 1)]


def torsion_profile(primes: Sequence[int], d: int) -> int:
    """The full free-witness count #{x : x^d = 1 mod N} = prod_p gcd(p-1, d)."""
    out = 1
    for p in primes:
        out *= gcd(p - 1, d)
    return out


def census_report(primes: Sequence[int], k_max: int = 8) -> Dict[str, object]:
    """Census values, tropical slopes, and root multiplicities."""
    levels = census_levels(primes)
    exps = [census_exponent(levels, k) for k in range(k_max + 1)]
    slopes = [exps[k + 1] - exps[k] for k in range(k_max)]
    mults = {k + 1: sum(1 for a in levels if a == k + 1) for k in range(k_max - 1)}
    return {
        "modulus": _product(primes),
        "levels": levels,
        "census": [2 ** e for e in exps],
        "exponents": exps,
        "slopes": slopes,
        "root_multiplicities": mults,
    }


def _product(xs: Sequence[int]) -> int:
    out = 1
    for x in xs:
        out *= x
    return out


if __name__ == "__main__":
    for S in ((3, 7), (7, 11), (17, 41), (3, 5, 17)):
        print(S, census_report(S))

"""Tropical fingerprint recovery: read the corner locus off a census curve.

Given census values T(0), T(1), ..., T(K) of a squarefree modulus, recover the
multiset of tropical roots {v2(p-1)} by finite differencing.  For a semiprime
the slope sequence goes 2 -> 1 -> 0 and the two drop points are the roots.
"""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple


def exponents_from_census(census: Sequence[int]) -> List[int]:
    """Recover E(k) = log2 T(k); the census is always a power of two."""
    exps: List[int] = []
    for t in census:
        e = t.bit_length() - 1
        if 1 << e != t:
            raise ValueError(f"census value {t} is not a power of two")
        exps.append(e)
    return exps


def tropical_slopes(exps: Sequence[int]) -> List[int]:
    """First differences: the number of roots still above level k."""
    return [exps[k + 1] - exps[k] for k in range(len(exps) - 1)]


def root_multiplicities(exps: Sequence[int]) -> Dict[int, int]:
    """Second differences: multiplicity of k+1 as a tropical root."""
    s = tropical_slopes(exps)
    return {k + 1: s[k] - s[k + 1] for k in range(len(s) - 1) if s[k] - s[k + 1] > 0}


def semiprime_fingerprint(census: Sequence[int]) -> Tuple[int, int]:
    """The unordered pair (min(a,b), max(a,b)) for a semiprime census."""
    exps = exponents_from_census(census)
    s = tropical_slopes(exps)
    if not s or s[0] != 2:
        raise ValueError("not a semiprime census (initial slope must be 2)")
    lo = next((k for k in range(len(s)) if s[k] < 2), None)
    hi = next((k for k in range(len(s)) if s[k] == 0), None)
    if lo is None or hi is None:
        raise ValueError("census truncated before both corners")
    return (lo, hi)


def census_of_levels(levels: Sequence[int], k_max: int) -> List[int]:
    return [2 ** sum(min(k, a) for a in levels) for k in range(k_max + 1)]


if __name__ == "__main__":
    for levels in ([1, 1], [2, 2], [4, 3], [1, 2, 4]):
        c = census_of_levels(levels, 8)
        e = exponents_from_census(c)
        print(f"levels {levels}: census {c}")
        print(f"   slopes {tropical_slopes(e)}   multiplicities {root_multiplicities(e)}")
        if len(levels) == 2:
            print(f"   recovered fingerprint {semiprime_fingerprint(c)} "
                  f"(true {tuple(sorted(levels))})")

"""Root-shuffling collision search: semiprimes with identical torsion profiles.

Two semiprimes N1 = p1 q1 and N2 = p2 q2 have the same free-witness profile
d |-> #{x : x^d = 1 mod N} if, at every prime ell, the valuation multisets
{v_ell(p-1), v_ell(q-1)} coincide.  Such pairs prove that no functional of the
profile can return a prime factor.
"""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Tuple

Key = Tuple[Tuple[int, Tuple[int, int]], ...]


def sieve(bound: int) -> List[int]:
    """Primes below `bound` by the sieve of Eratosthenes."""
    flags = bytearray([1]) * bound
    flags[0:2] = b"\x00\x00"
    i = 2
    while i * i < bound:
        if flags[i]:
            flags[i * i:bound:i] = bytearray(len(range(i * i, bound, i)))
        i += 1
    return [i for i in range(bound) if flags[i]]


def valuation(m: int, ell: int) -> int:
    k = 0
    while m % ell == 0:
        m //= ell
        k += 1
    return k


def shuffle_key(m: int, n: int, primes: List[int]) -> Key:
    """The family of local valuation multisets of the pair (m, n)."""
    out: List[Tuple[int, Tuple[int, int]]] = []
    for ell in primes:
        if ell > max(m, n):
            break
        pair = tuple(sorted((valuation(m, ell), valuation(n, ell))))
        if pair != (0, 0):
            out.append((ell, pair))  # type: ignore[arg-type]
    return tuple(out)


def find_profile_collisions(bound: int) -> List[Tuple[Tuple[int, int], Tuple[int, int]]]:
    """All pairs of distinct odd semiprimes below `bound` with equal profiles."""
    primes = sieve(bound)
    odd = [p for p in primes if p > 2]
    buckets: Dict[Key, List[Tuple[int, int]]] = {}
    for i, p in enumerate(odd):
        for q in odd[i + 1:]:
            if p * q >= bound:
                break
            buckets.setdefault(shuffle_key(p - 1, q - 1, primes), []).append((p, q))
    out: List[Tuple[Tuple[int, int], Tuple[int, int]]] = []
    for group in buckets.values():
        for i in range(len(group)):
            for j in range(i + 1, len(group)):
                out.append((group[i], group[j]))
    return out


def profile(p: int, q: int, d: int) -> int:
    return gcd(p - 1, d) * gcd(q - 1, d)


if __name__ == "__main__":
    for (p1, q1), (p2, q2) in find_profile_collisions(300)[:10]:
        vals1 = [profile(p1, q1, d) for d in range(1, 13)]
        vals2 = [profile(p2, q2, d) for d in range(1, 13)]
        assert vals1 == vals2
        print(f"{p1*q1:5d} = {p1}*{q1}   and   {p2*q2:5d} = {p2}*{q2}   profile {vals1}")
